    CONSTRAINT "jobs_fk_creator_scan_state_creator_source_id" FOREIGN KEY ("creator_source_id") REFERENCES "discovery_creator_sources" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "jobs_download_artifacts" (
