    "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    CONSTRAINT "jobs_fk_download_artifacts_run_id" FOREIGN KEY ("run_id") REFERENCES "jobs_download_job_runs" ("run_id") ON UPDATE NO ACTION ON DELETE CASCADE
);

