CREATE TABLE "jobs_download_jobs" (
    "job_id" TEXT NOT NULL CHECK ("job_id" IS NULL OR (length("job_id") = 32 AND "job_id" NOT GLOB '*[^0-9a-f]*')),
    "correlation_id" TEXT NOT NULL CHECK ("correlation_id" IS NULL OR (length("correlation_id") = 32 AND "correlation_id" NOT GLOB '*[^0-9a-f]*')),
    "state" TEXT NOT NULL CHECK ("state" IS NULL OR ("state" IN ('queued', 'metadata_pending', 'metadata_resolved', 'download_pending', 'downloaded_temp', 'upload_pending', 'uploaded', 'commit_pending', 'completed', 'compensating', 'failed_transient', 'failed_permanent', 'dead_lettered', 'already_downloaded', 'download_queued', 'cancelling', 'cancelled', 'ignored', 'provider_halted'))),
    "source_url" TEXT NOT NULL CHECK ("source_url" IS NULL OR (length("source_url") <= 4096)),
    "requested_by" TEXT CHECK ("requested_by" IS NULL OR (length("requested_by") <= 255)),
    "storage_key" TEXT CHECK ("storage_key" IS NULL OR (length("storage_key") <= 100)),
    "attempt_metadata" INTEGER NOT NULL DEFAULT 0,
    "attempt_download" INTEGER NOT NULL DEFAULT 0,
    "attempt_upload" INTEGER NOT NULL DEFAULT 0,
    "temp_file_ref" TEXT CHECK ("temp_file_ref" IS NULL OR (length("temp_file_ref") <= 2048)),
    "file_size_bytes" INTEGER,
    "content_hash_xxh128" TEXT CHECK ("content_hash_xxh128" IS NULL OR (length("content_hash_xxh128") <= 64)),
    "storage_version" TEXT CHECK ("storage_version" IS NULL OR (length("storage_version") <= 255)),
    "failure_kind" TEXT CHECK ("failure_kind" IS NULL OR ("failure_kind" IN ('unknown', 'transient', 'permanent', 'timeout', 'cancelled', 'interrupted', 'provider_blocked', 'stopped'))),
    "failure_code" TEXT CHECK ("failure_code" IS NULL OR (length("failure_code") <= 255)),
    "failure_message" TEXT CHECK ("failure_message" IS NULL OR (length("failure_message") <= 4096)),
    "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    "completed_at" INTEGER,
    "info_json_storage_path" TEXT CHECK ("info_json_storage_path" IS NULL OR (length("info_json_storage_path") <= 2048)),
    "info_json_content_hash_xxh128" TEXT CHECK ("info_json_content_hash_xxh128" IS NULL OR (length("info_json_content_hash_xxh128") <= 64)),
    "info_json_size_bytes" INTEGER,
    "meta_storage_path" TEXT CHECK ("meta_storage_path" IS NULL OR (length("meta_storage_path") <= 2048)),
    "priority" INTEGER NOT NULL DEFAULT 0,
    "ingest_origin" TEXT NOT NULL DEFAULT 'download' CHECK ("ingest_origin" IS NULL OR ("ingest_origin" IN ('download', 'local_import'))),
    "ignored_keyword" TEXT CHECK ("ignored_keyword" IS NULL OR (length("ignored_keyword") <= 200)),
    "source_kind" INTEGER NOT NULL DEFAULT 0,
    "status" TEXT NOT NULL DEFAULT 'queued' CHECK ("status" IS NULL OR ("status" IN ('queued', 'running', 'stopping', 'stopped', 'compensating', 'completed', 'completed_with_warnings', 'failed', 'already_downloaded', 'ignored'))),
    "stage" TEXT NOT NULL DEFAULT 'none' CHECK ("stage" IS NULL OR ("stage" IN ('none', 'metadata', 'duplicate_check', 'waiting_for_worker', 'media_acquire', 'primary_media_upload', 'meta_sidecar_upload', 'info_json_upload', 'thumbnail_upload', 'caption_upload', 'rich_metadata_write', 'finalize', 'cleanup', 'compensation', 'live_chat_upload'))),
    "stage_status" TEXT NOT NULL DEFAULT 'pending' CHECK ("stage_status" IS NULL OR ("stage_status" IN ('pending', 'running', 'retry_waiting', 'succeeded', 'skipped', 'warning', 'failed', 'stopped'))),
    "current_run_id" TEXT CHECK ("current_run_id" IS NULL OR (length("current_run_id") = 32 AND "current_run_id" NOT GLOB '*[^0-9a-f]*')),
    "current_run_number" INTEGER NOT NULL DEFAULT 0,
    "current_attempt" INTEGER NOT NULL DEFAULT 0,
    "current_artifact_key" TEXT CHECK ("current_artifact_key" IS NULL OR (length("current_artifact_key") <= 512)),
    "warning_count" INTEGER NOT NULL DEFAULT 0,
    "stop_requested_at" INTEGER,
    "stop_requested_by" TEXT CHECK ("stop_requested_by" IS NULL OR (length("stop_requested_by") <= 255)),
    "stop_reason" TEXT CHECK ("stop_reason" IS NULL OR (length("stop_reason") <= 512)),
    CONSTRAINT "jobs_PK_download_jobs" PRIMARY KEY ("job_id")
);

