    "media_guid" TEXT NOT NULL CHECK ("media_guid" IS NULL OR (length("media_guid") = 32 AND "media_guid" NOT GLOB '*[^0-9a-f]*')),
    "position" INTEGER NOT NULL,
    "added_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    CONSTRAINT "playlists_fk_user_playlist_items_media_guid" FOREIGN KEY ("media_guid") REFERENCES "media_media" ("media_guid") ON UPDATE NO ACTION ON DELETE CASCADE,
    CONSTRAINT "playlists_fk_user_playlist_items_playlist_id" FOREIGN KEY ("playlist_id") REFERENCES "playlists_user_playlists" ("playlist_id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "playlists_user_playlists" (
    "playlist_id" TEXT NOT NULL CHECK ("playlist_id" IS NULL OR (length("playlist_id") = 32 AND "playlist_id" NOT GLOB '*[^0-9a-f]*')),
    "owner_subject" TEXT NOT NULL CHECK ("owner_subject" IS NULL OR (length("owner_subject") <= 255)),
    "name" TEXT NOT NULL CHECK ("name" IS NULL OR (length("name") <= 255)),
    "description" TEXT CHECK ("description" IS NULL OR (length("description") <= 2048)),
    "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    CONSTRAINT "playlists_PK_user_playlists" PRIMARY KEY ("playlist_id")
);

CREATE TABLE "scheduling_scheduled_tasks" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
    "key" TEXT NOT NULL CHECK ("key" IS NULL OR (length("key") <= 100)),
    "task_type" TEXT NOT NULL CHECK ("task_type" IS NULL OR (length("task_type") <= 100)),
    "cron" TEXT CHECK ("cron" IS NULL OR (length("cron") <= 255)),
    "interval_seconds" INTEGER,
    "timezone" TEXT NOT NULL DEFAULT 'UTC' CHECK ("timezone" IS NULL OR (length("timezone") <= 100)),
    "enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("enabled" IS NULL OR ("enabled" IN (0, 1))),
    "catchup_policy" TEXT NOT NULL DEFAULT 'Coalesce' CHECK ("catchup_policy" IS NULL OR (length("catchup_policy") <= 32)),
    "last_attempt_at" INTEGER,
    "last_success_at" INTEGER,
    "next_due_at" INTEGER,
    "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    "last_updated" INTEGER,
    "last_run_status" TEXT CHECK ("last_run_status" IS NULL OR (length("last_run_status") <= 32)),
    "retention_days" INTEGER NOT NULL DEFAULT 0,
    "include_failed" INTEGER NOT NULL DEFAULT 0 CHECK ("include_failed" IS NULL OR ("include_failed" IN (0, 1))),
    CONSTRAINT "scheduling_ck_scheduled_tasks_interval_positive" CHECK (((interval_seconds IS NULL) OR (interval_seconds > 0))),
    CONSTRAINT "scheduling_ck_scheduled_tasks_key_format" CHECK (length("key") BETWEEN 2 AND 100 AND "key" NOT GLOB '*[^a-z0-9-]*'),
    CONSTRAINT "scheduling_ck_scheduled_tasks_retention_days_nonnegative" CHECK ((retention_days >= 0)),
    CONSTRAINT "scheduling_ck_scheduled_tasks_trigger_xor" CHECK ((((cron IS NOT NULL) AND (interval_seconds IS NULL)) OR ((cron IS NULL) AND (interval_seconds IS NOT NULL))))
);

CREATE TABLE "statistics_account_daily_states" (
    "day" TEXT NOT NULL,
    "account_id" INTEGER NOT NULL,
    "state" TEXT NOT NULL CHECK ("state" IS NULL OR (length("state") <= 32)),
    "job_count" INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "statistics_pk_account_daily_states" PRIMARY KEY ("day", "account_id", "state"),
    CONSTRAINT "statistics_fk_account_daily_states_account_id" FOREIGN KEY ("account_id") REFERENCES "metadata_accounts" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "statistics_channel_media_downloads" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
