    "account_id" INTEGER NOT NULL,
    "platform" TEXT NOT NULL CHECK ("platform" IS NULL OR (length("platform") <= 50)),
    "bytes" INTEGER NOT NULL DEFAULT 0,
    "duration_seconds" REAL NOT NULL DEFAULT 0,
    "completed_at" INTEGER NOT NULL,
    CONSTRAINT "statistics_fk_channel_media_downloads_account_id" FOREIGN KEY ("account_id") REFERENCES "metadata_accounts" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "statistics_creator_source_daily_states" (
