CREATE TABLE "storage_storage_keys" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
    "key" TEXT NOT NULL CHECK ("key" IS NULL OR (length("key") <= 100)),
    "method" TEXT NOT NULL CHECK ("method" IS NULL OR (length("method") <= 50)),
    "description" TEXT CHECK ("description" IS NULL OR (length("description") <= 500)),
    "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', 'now') AS INTEGER) * 1000000 + CAST(substr(strftime('%f', 'now'), 4, 3) AS INTEGER) * 1000),
    "last_updated" INTEGER,
    "worker_tag" TEXT CHECK ("worker_tag" IS NULL OR (length("worker_tag") <= 50)),
    CONSTRAINT "storage_ck_storage_keys_key_format" CHECK (length("key") BETWEEN 2 AND 100 AND "key" NOT GLOB '*[^a-z0-9-]*')
);

CREATE TABLE "storage_storage_keys_local" (
    "storage_key_id" INTEGER NOT NULL,
