    CONSTRAINT "storage_PK_storage_keys_local" PRIMARY KEY ("storage_key_id"),
    CONSTRAINT "storage_fk_storage_keys_local_storage_key_id" FOREIGN KEY ("storage_key_id") REFERENCES "storage_storage_keys" ("id") ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE "storage_storage_keys_network" (
    "storage_key_id" INTEGER NOT NULL,
    "protocol" TEXT NOT NULL CHECK ("protocol" IS NULL OR ("protocol" IN ('ftp', 'ftps', 'sftp', 'nfs', 'smb', 'cifs'))),
    "host" TEXT NOT NULL CHECK ("host" IS NULL OR (length("host") <= 255)),
    "port" INTEGER,
    "username" TEXT CHECK ("username" IS NULL OR (length("username") <= 255)),
    "base_path" TEXT CHECK ("base_path" IS NULL OR (length("base_path") <= 2048)),
    "mount_path" TEXT CHECK ("mount_path" IS NULL OR (length("mount_path") <= 2048)),
    "share_name" TEXT CHECK ("share_name" IS NULL OR (length("share_name") <= 255)),
    "domain" TEXT CHECK ("domain" IS NULL OR (length("domain") <= 255)),
    "export_path" TEXT CHECK ("export_path" IS NULL OR (length("export_path") <= 2048)),
    "nfs_user_id" INTEGER,
    "nfs_group_id" INTEGER,
    CONSTRAINT "storage_PK_storage_keys_network" PRIMARY KEY ("storage_key_id"),
    CONSTRAINT "storage_fk_storage_keys_network_storage_key_id" FOREIGN KEY ("storage_key_id") REFERENCES "storage_storage_keys" ("id") ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE "storage_storage_keys_object_azure_blob" (
    "storage_key_id" INTEGER NOT NULL,
    "credential_mode" TEXT NOT NULL CHECK ("credential_mode" IS NULL OR ("credential_mode" IN ('account_key', 'connection_string', 'sas_url'))),
    "container_name" TEXT CHECK ("container_name" IS NULL OR (length("container_name") <= 255)),
    "azure_account_name" TEXT CHECK ("azure_account_name" IS NULL OR (length("azure_account_name") <= 255)),
