CREATE TABLE "storage_storage_keys_object_google_cloud_storage" (
    "storage_key_id" INTEGER NOT NULL,
    "bucket_name" TEXT NOT NULL CHECK ("bucket_name" IS NULL OR (length("bucket_name") <= 255)),
    "credential_mode" TEXT NOT NULL CHECK ("credential_mode" IS NULL OR ("credential_mode" IN ('credentials_json', 'credentials_file_path', 'workload_identity', 'default_credentials'))),
