    CONSTRAINT "storage_PK_storage_keys_object_google_cloud_storage" PRIMARY KEY ("storage_key_id"),
    CONSTRAINT "storage_fk_storage_keys_object_google_cloud_storage_storage_key_id" FOREIGN KEY ("storage_key_id") REFERENCES "storage_storage_keys" ("id") ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE "storage_storage_keys_object_s3_compatible" (
    "storage_key_id" INTEGER NOT NULL,
    "provider" TEXT NOT NULL CHECK ("provider" IS NULL OR ("provider" IN ('aws_s3', 'min_io', 'digital_ocean_spaces'))),
    "bucket_name" TEXT NOT NULL CHECK ("bucket_name" IS NULL OR (length("bucket_name") <= 255)),
    "region" TEXT CHECK ("region" IS NULL OR (length("region") <= 255)),
    "endpoint" TEXT CHECK ("endpoint" IS NULL OR (length("endpoint") <= 2048)),
