    CONSTRAINT "storage_fk_storage_keys_object_s3_compatible_storage_key_id" FOREIGN KEY ("storage_key_id") REFERENCES "storage_storage_keys" ("id") ON UPDATE CASCADE ON DELETE CASCADE
);

